import { useState } from "react";

export function LessonEditor({ lessons, onSave, onDelete }) {
  const [title, setTitle] = useState("");

  function handleSubmit(event) {
    event.preventDefault();                 // we save ourselves; no page reload.
    if (!title.trim()) return;
    onSave(title.trim());
    setTitle("");
  }

  return (
    <form onSubmit={handleSubmit}>          {/* Enter and click both submit. */}
      <label>
        Title
        <input value={title} onChange={(e) => setTitle(e.target.value)} />
      </label>
      <button type="submit">Save</button>
      <ul>
        {lessons.map((l) => (
          <li key={l.id}>
            {l.title}{" "}
            <button type="button" onClick={() => onDelete(l.id)}>Delete {l.title}</button>
          </li>
        ))}
      </ul>
    </form>
  );
}
```

| Write | Meaning |
|---|---|
| `onClick={save}`. | call save later, with the event. |
| `onClick={save()}`. | call save now; wrong. |
| `onClick={() => remove(id)}`. | call remove later with id. |
| `onSubmit` on form. | handles click and Enter. |

